class OfflineMain extends Main{static init(){this.round=1,this.stage=1,$("#goal").textContent=this.goal;for(let i=1;i<=this.playNum;i++)this.pars.push({name:`Player${i}`,money:this.start,operation:"",target:"",variation:0}),$(`#Player${i} > div > #money`).textContent=this.start;for(let i=this.playNum+1;i<=6;i++)$(`#Player${i}`).style.visibility="hidden",$(`#p${i}`).style.visibility="hidden";this.cleanLog()}static async game(){await sleep(2500);let players=[];for(let i=0;i<this.playNum;i++)players.push(new OfflinePlayer(i,this));this.init(),$("#log1").textContent="初始化完成, 游戏即将开始",await sleep(1500);for(let i=0;i<21;i++){$("#log1").textContent="新一轮开始",this.updateInfo(),await sleep(500);for(let i=0;i<this.playNum;i++)$("#log2").textContent=`请 Player${i+1} 选择操作`,players[i].disableBtn(),await players[i].getOperation(),$("#log2").textContent=`本轮操作为: ${TRANSLATE[this.pars[i].operation]} ${this.pars[i].target}`,await sleep(1e3),$("#log3").textContent="请将设备移交给下一位玩家",await sleep(500),$("#log3").textContent="";if($("#log4").textContent="等待本轮结算",await sleep(1e3),this.cleanLog(),this.updateUI(),await sleep(2e4),this.pars.find(p=>p.money>=this.goal)){$("#log1").textContent="已有玩家实现小目标，游戏结束";break}this.cleanLog(),this.round+=1,await sleep(1e3)}let rank=[];for(let i=0;i<this.playNum;i++)rank.push({name:`Player${i+1}`,money:this.pars[i].money});rank.sort((a,b)=>b.money-a.money),$("#log2").textContent="游戏结束",$("#log3").textContent="最终排名",$("#log4").textContent=`No. 1: ${rank[0].name} 资金${rank[0].money}; No. 4: ${""|rank[3].name} 资金${0|rank[3].money};`,$("#log5").textContent=`No. 2: ${rank[1].name} 资金${rank[1].money}; No. 5: ${""|rank[4].name} 资金${"0"|rank[4].money};`,$("#log6").textContent=`No. 3: ${rank[2].name} 资金${rank[2].money}; No. 6: ${""|rank[5].name} 资金${0|rank[5].money};`}}class OfflinePlayer extends Player{attBtn;defBtn;stoBtn;p1Btn;p2Btn;p3Btn;p4Btn;p5Btn;p6Btn;cancelBtn;handles={attBtn:this.prsAtt.bind(this),defBtn:this.prsDef.bind(this),stoBtn:this.prsSto.bind(this),p1Btn:this.target.bind(this,"Player1"),p2Btn:this.target.bind(this,"Player2"),p3Btn:this.target.bind(this,"Player3"),p4Btn:this.target.bind(this,"Player4"),p5Btn:this.target.bind(this,"Player5"),p6Btn:this.target.bind(this,"Player6"),cancelBtn:this.prsCancel.bind(this)};constructor(id,Main){super(id,Main),this.attBtn=$("#attBtn"),this.defBtn=$("#defBtn"),this.stoBtn=$("#stoBtn"),this.p1Btn=$("#p1"),this.p2Btn=$("#p2"),this.p3Btn=$("#p3"),this.p4Btn=$("#p4"),this.p5Btn=$("#p5"),this.p6Btn=$("#p6"),this.cancelBtn=$("#cancel")}disableBtn(){this.p1Btn.disabled=0==this.id,this.p2Btn.disabled=1==this.id,this.p3Btn.disabled=2==this.id,this.p4Btn.disabled=3==this.id,this.p5Btn.disabled=4==this.id,this.p6Btn.disabled=5==this.id}}